message.content:
{
  "candidate_edge_types": [
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent agent action incorporates information or an artifact produced by an earlier observation or action as a required input, such as a script constant, command argument, or parameter value.",
      "source_description": "An earlier observation or action that produced a result or artifact (e.g., derived board position data from image analysis).",
      "target_description": "A later agent action that consumes that earlier result or artifact as an input."
    },
    {
      "name": "VERIFIES_PRODUCED_OUTPUT",
      "definition": "A subsequent agent action inspects an artifact generated by an earlier action to confirm that its content matches the expected requirements.",
      "source_description": "An earlier action that produced an output artifact (e.g., a written result file).",
      "target_description": "A later inspection action that checks the content or existence of that artifact."
    },
    {
      "name": "CONTINUES_PRIOR_EXAMINATION",
      "definition": "A subsequent action retrieves an additional portion of the same resource that an earlier observation began inspecting, extending the same line of investigation.",
      "source_description": "An earlier partial observation of a resource (e.g., a portion of a file).",
      "target_description": "A later observation retrieving a further portion of the same resource."
    },
    {
      "name": "TRIGGERS_TASK_COMPLETION",
      "definition": "A verified or successful execution result leads the agent to declare the task complete.",
      "source_description": "An observed execution result that confirms the task's requirements are met.",
      "target_description": "A subsequent task-completion action or decision."
    }
  ]
}

